@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;700&display=swap');
:root {
  --font-family: 'Space Grotesk', system-ui, sans-serif;
  --color-background: #111310;
  --color-card-bg: #191c18;
  --color-card-border: rgb(244 243 238 / 15%);
  --color-card-shadow: rgb(0 0 0 / 40%);
  --color-header: #f4f3ee;
  --color-header-subtext: #b7bdb2;
  --color-label: #f4f3ee;
  --color-input-border: rgb(244 243 238 / 25%);
  --color-input-text: #f4f3ee;
  --color-focus-border: #5dc4a4;
  --color-submit-btn-bg: #5dc4a4;
  --color-submit-btn-text: #111310;
  --color-required: #5dc4a4;
  --color-error: #f0a08a;
  --color-link: #5dc4a4;
  --color-html-text: #b7bdb2;
  --color-html-link: #5dc4a4;
  --border-radius-card: 8px;
  --border-radius-input: 6px;
  --box-shadow-card: 0 12px 40px var(--color-card-shadow);
}
body { background: var(--color-background); }
input, select, textarea { background: #111310; color: var(--color-input-text); }
input::placeholder, textarea::placeholder { color: #565c53; opacity: 1; }
input[type=number]::-webkit-inner-spin-button, input[type=number]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
input[type=number] { -moz-appearance: textfield; }
#submit-btn { font-weight: 700; letter-spacing: 0.02em; }
#submit-btn:hover { filter: brightness(1.08); }

.error-show { font-size: 0 !important; }
.error-show::after { font-size: 13px; }
.error-field-0.error-show::after { content: 'Escribe tu nombre'; }
.error-field-1.error-show::after { content: 'Escribe tu WhatsApp a 10 dígitos, solo números'; }
.error-field-2.error-show::after { content: 'Revisa el correo: algo como ana@correo.com'; }
.error-field-3.error-show::after { content: 'Elige una opción'; }

:root { --color-input-bg: #111310; }
.form-header p { color: var(--color-header-subtext); }
.multiselect-option label { color: var(--color-label); }
input[type='radio'] { accent-color: #5dc4a4; }

input, textarea, select, button { font-family: inherit; }

