// Meta rechaza variables vacías, con saltos de línea o de más de 200 caracteres.
const flat = (v) => (String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, 200)) || '—';
// Un celular de México son 10 dígitos; se acepta también con lada de país (52 o 521).
const tenDigits = (v) => {
  const d = String(v ?? '').replace(/\D/g, '');
  const local = d.length === 12 && d.startsWith('52') ? d.slice(2) : d.length === 13 && d.startsWith('521') ? d.slice(3) : d;
  return /^[1-9]\d{9}$/.test(local) ? local : null;
};
return $input.all().map(({ json: f }) => {
  const whatsapp = tenDigits(f['WhatsApp']);
  return { json: {
    valido: whatsapp !== null,
    nombre: flat(f['Nombre']),
    whatsapp: whatsapp ?? String(f['WhatsApp'] ?? ''),
    correo: flat(f['Correo']),
    tratamiento: flat(f['¿Qué te interesa?']),
    mensaje: flat(f['Cuéntanos un poco más']),
  } };
});

